EDITS = [('E1 version', 'VERSION = "S656"', 'VERSION = "S831"'), ('E2 docstring', 'S643 (the owner, 06:43 IST 25-Oct-2026)', 'S831_PROCROOM_SIMPLE (D982; the owner\'s "Final" on the mock-up v4, 14:40 IST 14-Nov-2026; built in the Scan App chat, session 461)\n    HIS PAGE SIMPLIFIED (GET /procroom; the owner\'s only; NO staff screen changes): the tiles (spent, procedure revenue, procedures\n    done, Fibrecast in stock today, waiting for you, the morning screen), each a link; Start here in three steps; Expenses and revenue\n    -- the financial year month by month, the X-ray page\'s way: bought, procedures, ILI revenue, other procedures\' revenue, revenue\n    less bought (NO per-procedure column); each month opens to what was bought (dealer challans) and the procedures done, one row per\n    PATIENT SLIP with its fee and its items, editable -- saved through the morning screen\'s own save (POST /procroom/used, day by day;\n    a slip\'s earlier record voided, kept). Revenue = the fees on those patient slips (fin_span: price less discount, a rejected\n    discount not taken off; \'nahi hua\' and an approved cancellation left out), from the morning screen\'s floor. Stock now: his count\n    and his reorder level in one Save; GLOVES IN WHOLE PAIRS, never a decimal (a box holds proc.gloves_box pairs). Yuvika\'s papers are\n    "dealer challans" everywhere on this page ("slip" alone means the patient slip). The rest folded; a fixed "Top" button.\n\nS643 (the owner, 06:43 IST 25-Oct-2026)'), ('E3 stock_view keeps bought and used', '            if bad:\n                row["why"] = "set the gloves box size to count it"', '            row["bought"], row["used"] = bought, used                  # S831: shown on his Stock now\n            if bad:\n                row["why"] = "set the gloves box size to count it"'), ('E4 owner_view hands its counted rows on', '"morning_on": mon, "behind": behind}', '"morning_on": mon, "behind": behind, "allrows": allrows}'), ('E5 the new functions before his page', "# ---------------------------------------------------------------------------------------------- the owner's page\n", '# ---------------------------------------------------------------------------------------------- S831: his simplified page (D982)\ndef _is_gloves(it):\n    return (it.get("unit") == "box") and ("glove" in norm(it.get("name")))\n\n\ndef _box(db):\n    """Pairs in a box of gloves (his setting proc.gloves_box: a box of 100 gloves = 50 pairs); None until he sets it."""\n    v = _num(_setting(db, "proc.gloves_box", ""))\n    return v if (v is not None and v > 0) else None\n\n\ndef pairs_word(pairs):\n    """Gloves in whole pairs, never a decimal: \'8 pairs\', \'1 pair\'."""\n    n = int(round(pairs or 0))\n    return "%d pair%s" % (n, "" if abs(n) == 1 else "s")\n\n\ndef gloves_word(boxes, box):\n    """A gloves quantity kept in boxes, said in boxes and whole pairs: \'2 boxes + 14 pairs\'. \'\' when the box size is not set."""\n    if boxes is None or not box:\n        return ""\n    p = int(round(boxes * box))\n    neg, p = p < 0, abs(p)\n    b, r = divmod(p, max(1, int(round(box))))\n    parts = (["%d box%s" % (b, "" if b == 1 else "es")] if b else []) + ([pairs_word(r)] if (r or not b) else [])\n    return ("-" if neg else "") + " + ".join(parts)\n\n\ndef _month_end(ym):\n    y, m = int(ym[:4]), int(ym[5:7])\n    nxt = datetime.date(y + (m == 12), m % 12 + 1, 1)\n    return (nxt - datetime.timedelta(days=1)).isoformat()\n\n\ndef fin_span(lo, hi):\n    """S831: the patient slips with a procedure from day lo to day hi -- the parent\'s slip book, READ ONLY, as fin_day reads it\n    (series X-ray / Proc, state ok, at least one procedure line) -- each with its procedures, each procedure\'s group (\'cast\',\n    \'ili\' or \'\' = other) and FEE in rupees: slip_item.price_p less its discount_p, a discount he or Shavez REJECTED not taken off\n    (the parent\'s day check\'s own rule). Left out: a slip Docterz\'s report (come for that day) does not have -- \'nahi hua\', as the\n    morning screen leaves it out -- and a slip whose cancellation was approved. [] for an empty span; None when the slip book\n    cannot be read (never taken as \'no procedures\')."""\n    if not lo or not hi or lo > hi:\n        return []\n    try:\n        con = _fin()\n    except sqlite3.Error:\n        con = None\n    if con is None:\n        return None\n    try:\n        icols = {r[1] for r in con.execute("PRAGMA table_info(slip_item)")}\n        tabs = {r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type=\'table\'")}\n        arrived = {r[0] for r in con.execute("SELECT DISTINCT business_date FROM clinic_day_revenue WHERE business_date BETWEEN ? AND ?", (lo, hi))}\n        proc = {}\n        for r in con.execute("SELECT business_date, clinic_id FROM clinic_day_line WHERE section=\'proc\' AND business_date BETWEEN ? AND ?", (lo, hi)):\n            proc.setdefault(r[0], set()).add(r[1])\n        grp = {r[0]: (r[1] or "") for r in con.execute("SELECT id, grp FROM owner_service")}\n        rejected, cancelled = set(), set()\n        if "slip_adjust" in tabs:\n            last = {}\n            for r in con.execute("SELECT item_id, state FROM slip_adjust WHERE kind IN (\'discount\',\'free\') AND item_id IS NOT NULL "\n                                 "AND state<>\'replaced\' ORDER BY id"):\n                last[r[0]] = r[1]\n            rejected = {k for k, v in last.items() if v == "rejected"}\n            cancelled = {r[0] for r in con.execute("SELECT slip_id FROM slip_adjust WHERE kind=\'cancel\' AND state=\'approved\'")}\n        disc = "i.discount_p" if "discount_p" in icols else "0"\n        rows = con.execute("SELECT s.id AS sid, s.slip_no AS no, s.day AS day, s.clinic_id AS cid, i.id AS iid, i.service_id AS svc, "\n                           "i.name AS name, i.price_p AS price, " + disc + " AS disc FROM slip s JOIN slip_item i ON i.slip_id=s.id "\n                           "WHERE s.series=\'xp\' AND s.state=\'ok\' AND s.day BETWEEN ? AND ? AND i.kind=\'proc\' "\n                           "ORDER BY s.day, s.slip_no, i.sort, i.id", (lo, hi)).fetchall()\n    except sqlite3.Error:\n        return None\n    finally:\n        con.close()\n    out, by = [], {}\n    for r in rows:\n        if r["sid"] in cancelled:\n            continue\n        cid = (r["cid"] or "").strip()\n        if r["day"] in arrived and cid and cid not in proc.get(r["day"], ()):\n            continue                                                 # Docterz\'s report has come and has no procedure for it: nahi hua\n        s = by.get(r["sid"])\n        if s is None:\n            s = by[r["sid"]] = {"ref": "xp:%d" % r["sid"], "id": r["sid"], "no": r["no"], "day": r["day"], "items": [], "fee": 0.0}\n            out.append(s)\n        d = 0 if r["iid"] in rejected else int(r["disc"] or 0)\n        fee = max(0, int(r["price"] or 0) - d) / 100.0\n        s["items"].append({"name": r["name"] or "", "grp": _grp_of(r["name"] or "", grp.get(r["svc"], "")), "fee": fee})\n        s["fee"] += fee\n    return out\n\n\ndef waiting_papers(db):\n    """S831: the dealer challans on the desk in Procedure room that count but have no lines saved yet (never his orders), oldest first."""\n    try:\n        rows = db.execute("SELECT b.* FROM bills b WHERE " + _paper_sql(db, "b") + " AND " + _not_order_sql("b")).fetchall()\n    except sqlite3.Error:\n        return []\n    out = []\n    for r in rows:\n        b = dict(r)\n        if saved_lines(db, b):\n            continue\n        out.append({"id": b["id"], "stamp": _stamp(b), "day": _pday(b), "vendor": b.get("vendor") or ""})\n    return sorted(out, key=lambda x: (x["day"] or "", x["id"]))\n\n\ndef _fill(db, s):\n    """One patient slip\'s items as the morning screen pre-fills them: what was saved for it, else the last time that procedure was\n    entered; its added items; whether it is saved; its gloves by his allowance."""\n    us, ul = saved_use(db, s["ref"])\n    by = {}\n    for u in ul:\n        if u["lkey"]:\n            by[u["lkey"]] = u\n    for l in s["kit"]:\n        prev = by.get(l["key"]) if us else _usual(db, l["kitkey"])\n        l["size"] = (prev or {}).get("size") or ""\n        l["qty"] = _plain((prev or {}).get("qty")) if (prev and prev.get("qty") is not None) else ""\n        l["on"] = bool(prev and (prev.get("qty") or 0) > 0)\n        l["choice"] = (prev or {}).get("size") or ""\n    s["added"] = [u for u in sorted(ul, key=lambda u: u["lkey"]) if u["src"] == "added"]\n    s["saved"] = us\n    s["gloves"] = sum(gloves_pairs(db, g1) for g1 in s["grps"])\n    return s\n\n\ndef _n(x):\n    """Rupees without the sign, Indian grouping; \'—\' for none."""\n    return "—" if x is None else rs(x).replace("₹", "")\n\n\ndef page_model(db, ym):\n    """S831: his page for a month -- the tiles, the Start-here strip, the financial year month by month (bought, procedures,\n    ILI revenue, other procedures\' revenue, revenue less bought; each month: what was bought, and the procedures done one row\n    per patient slip), the stock now, and the owner_view of the month for the folded sections."""\n    today = _today()\n    this = today.strftime("%Y-%m")\n    if ym > this:\n        ym = this\n    fy0 = fy_of(datetime.date(int(ym[:4]), int(ym[5:7]), 1))\n    months = fy_months(fy0, this if fy_of(today) == fy0 else None)\n    v = owner_view(db, ym=ym)\n    items = v["products"]\n    byid = {i["id"]: i for i in items}\n    usable = [i for i in items if i["state"] in ("active", "rare")]\n    allrows = v["allrows"]\n    floor = morning_from(db)\n    box = _box(db)\n    wp = waiting_papers(db)\n    wph = [p for p in photo_rows(db, None) if not p["checked_at"]]\n    lo = max(floor, months[0] + "-01")\n    hi = min(today.isoformat(), _month_end(months[-1]))\n    fs = fin_span(lo, hi)\n    book_ok = fs is not None\n    fsm = {}\n    for s in (fs or []):\n        fsm.setdefault(s["day"][:7], []).append(s)\n    rows = []\n    for mo in months:\n        mine = [d for d in allrows if d["mo"] == mo]\n        here = [d for d in mine if d["place"] == "proc"]\n        oth = [d for d in mine if d["place"] != "proc"]\n        bought = sum(d["amt"] or 0 for d in here if d["amt"] is not None)\n        nch = len({_slip_key(d) for d in here})\n        wpm = [p for p in wp if (p["day"] or "")[:7] == mo]\n        whm = [p for p in wph if p["ym"] == mo]\n        before = mo < floor[:7]\n        x = {"ym": mo, "label": _mlabel(mo), "short": _mlabel(mo).split(" ")[0], "bought": bought, "nch": nch, "before": before,\n             "lines": [{"id": d["id"], "bid": d["bill_id"] if d["src"] == "paper" else None, "stamp": d["stamp"] or "", "vendor": d["vendor"] or "",\n                        "when": d["when"], "name": (byid.get(d["item_id"]) or {}).get("name") or d["name"], "brand": d["brand"],\n                        "qty": d["qty"], "unit": d["unit"], "eff": d["eff"], "amt": d["amt"]} for d in here],\n             "waiting": wpm, "else_n": len(oth), "else_amt": sum(d["amt"] or 0 for d in oth if d["amt"] is not None),\n             "procs": None, "ili": None, "other": None, "less": None, "cast_n": 0, "ili_n": 0, "other_n": 0, "slips": [], "nahi": 0}\n        wparts = (["photo" if len(whm) == 1 else "%d photos" % len(whm)] if whm else []) + \\\n                 (["%d challan%s" % (len(wpm), "" if len(wpm) == 1 else "s")] if wpm else [])\n        x["wait"] = (" + ".join(wparts) + " waiting") if wparts else ""\n        x["bwords"] = ("%d counted" % nch if nch else "none counted yet") + \\\n                      ("".join(" · %s waiting on the desk" % p["stamp"] for p in wpm[:3]) + (" · …" if len(wpm) > 3 else ""))\n        if not before and book_ok:\n            ps = fsm.get(mo, [])\n            its = [i for s in ps for i in s["items"]]\n            x["procs"] = len(its)\n            x["cast_n"] = len([i for i in its if i["grp"] == "cast"])\n            x["ili_n"] = len([i for i in its if i["grp"] == "ili"])\n            x["other_n"] = len(its) - x["cast_n"] - x["ili_n"]\n            x["ili"] = sum(i["fee"] for i in its if i["grp"] == "ili")\n            x["other"] = sum(i["fee"] for i in its if i["grp"] != "ili")\n            x["less"] = x["ili"] + x["other"] - bought\n            fee = {s["ref"]: s for s in ps}\n            for day in sorted({s["day"] for s in ps}, reverse=True):\n                fd = fin_day(day, usable)\n                for s in fd["slips"]:\n                    if s["confirmed"] is False:\n                        x["nahi"] += 1\n                        continue\n                    if s["ref"] not in fee:\n                        continue\n                    s = _fill(db, s)\n                    s["day"], s["id"], s["fee"] = day, fee[s["ref"]]["id"], fee[s["ref"]]["fee"]\n                    for a in s["added"]:\n                        a["iname"] = (byid.get(a["item_id"]) or {}).get("name") or a["name"]\n                    x["slips"].append(s)\n                x["slips"].sort(key=lambda s: (s["day"], s["no"]), reverse=True)\n        rows.append(x)\n    known = [x for x in rows if x["procs"] is not None]\n    year = {"bought": sum(x["bought"] for x in rows), "procs": sum(x["procs"] for x in known) if known else None,\n            "ili": sum(x["ili"] for x in known) if known else None, "other": sum(x["other"] for x in known) if known else None,\n            "less": sum(x["less"] for x in known) if known else None}\n    cur = next((x for x in rows if x["ym"] == ym), rows[-1])\n    # the stock now (his count + bought since - used since), gloves in boxes and whole pairs\n    st = []\n    for s in v["stock"]:\n        it = byid.get(s["id"]) or {}\n        gl = _is_gloves(it)\n        c = s["count"]\n        if gl:\n            ph = "pairs"\n            last = (pairs_word(c["qty"] * box) if box else _plain(c["qty"]) + " " + it["unit"]) if c else ""\n            bought = gloves_word(s.get("bought"), box) if c else "—"\n            used = pairs_word((s.get("used") or 0) * box) if (c and box and s.get("used") is not None) else "—"\n            stock = gloves_word(s["stock"], box) if s["stock"] is not None else ""\n            reo = str(int(round(it["reorder"] * box))) if (it.get("reorder") is not None and box) else ""\n        else:\n            ph = it.get("unit") or ""\n            last = (_plain(c["qty"]) + " " + ph) if c else ""\n            bought = (_plain(s.get("bought")) + " " + ph) if (c and s.get("bought") is not None) else "—"\n            used = (_plain(s.get("used")) + " " + ph) if (c and s.get("used") is not None) else "—"\n            stock = (_plain(s["stock"]) + " " + ph) if s["stock"] is not None else ""\n            reo = _plain(it.get("reorder")) if it.get("reorder") is not None else ""\n        st.append({"id": s["id"], "name": s["name"], "gloves": gl, "ph": ph, "last": last, "day": _dmy(c["day"]) if c else "no count yet",\n                   "bought": bought, "used": used, "stock": stock or (s["why"] or ("after the count" if not c else "—")),\n                   "red": bool(s["order"]), "reorder": reo})\n    fib = []\n    for s in v["stock"]:\n        nm = byid.get(s["id"], {}).get("name") or ""\n        if norm(nm).startswith("fibrecast") and byid.get(s["id"], {}).get("state") == "active":\n            fib.append({"size": re.sub(r"(?i)^\\s*fibre\\s*cast(\\s+bandage)?\\s*", "", nm).strip() or nm, "counted": s["count"] is not None, "red": bool(s["order"]),\n                        "word": ("%s roll%s" % (_plain(s["stock"]), "" if s["stock"] == 1 else "s")) if s["stock"] is not None else "—"})\n    counts = last_counts(db)\n    missing = [i for i in items if i["state"] == "active" and i["id"] not in counts]\n    od = open_days(db)\n    mon = morning_on(db)\n    if od is None:\n        mo_n, mo_w = None, "the slip book could not be read"\n    else:\n        mo_n = sum(x["n"] for x in od)\n        mo_w = ("nothing to fill" if not mo_n else\n                ("patient slips of %s to fill" % _dmy(od[0]["day"])[:5]) if len(od) == 1 else ("patient slips of %d days to fill" % len(od)))\n    if not mon:\n        mo_w += " · off for the staff"\n    gc = _setting(db, "proc.gloves_cast", dict(ALLOW)["proc.gloves_cast"]) or "0"\n    gi = _setting(db, "proc.gloves_ili", dict(ALLOW)["proc.gloves_ili"]) or "0"\n    wn = len(wp) + len(wph)\n    wwords = " · ".join((["%d dealer challan%s" % (len(wp), "" if len(wp) == 1 else "s")] if wp else []) +\n                        (["%d photo%s" % (len(wph), "" if len(wph) == 1 else "s")] if wph else [])) or "nothing waiting"\n    photos = [{"id": p["id"], "ym": p["ym"], "mlabel": _mlabel(p["ym"]),\n               "state": {"read": "read, waiting for your rates", "failed": "could not be read — type its lines"}.get(p["read_state"], "being read")}\n              for p in wph]\n    return {"v": v, "ym": ym, "label": _mlabel(ym), "fy": fy0, "months": rows, "year": year, "cur": cur, "book_ok": book_ok, "floor": floor,\n            "usable": usable, "stock": st, "fib": fib, "fib_counted": any(f["counted"] for f in fib),\n            "wait_n": wn, "wait_words": wwords, "mo": {"n": mo_n, "words": mo_w},\n            "s1": {"done": bool(counts), "missing": len(missing)}, "s2": {"papers": wp, "photos": photos, "n": wn},\n            "s3": {"on": mon, "behind": mo_n or 0},\n            "gl": {"cast": gc, "ili": gi, "box": box, "box_word": ("%d gloves (%s)" % (int(round(box * 2)), pairs_word(box))) if box else "not set yet"},\n            "items_json": json.dumps([[i["id"], i["name"]] for i in usable], ensure_ascii=True).replace("<", "\\\\u003c")}\n\n\nclass _DayForm(object):\n    """One day\'s part of his month Save, in the shape save_morning reads: the form\'s fields, and only that day\'s patient slips."""\n\n    def __init__(self, form, refs):\n        self.form, self.refs = form, list(refs)\n\n    def get(self, k, d=None):\n        return self.form.get(k, d)\n\n    def getlist(self, k):\n        return list(self.refs) if k == "refs" else (self.form.getlist(k) if hasattr(self.form, "getlist") else [])\n\n\nSAVE_WORDS = (("Slip book abhi padh nahi paaye", "the slip book could not be read just now"), ("size chunein", "choose a size"),\n              ("ginti sahi likhein", "type a correct number"), ("yeh size list mein nahi", "that size is not on the list"),\n              ("yeh list mein nahi", "that is not on the list"), ("list se cheez chunein", "choose the added item from your list"),\n              ("kitna, likhein", "type how many"))\n\n\ndef save_month(db, ym, form, who=None):\n    """S831: his one Save of a month\'s procedures on his page -- THROUGH THE MORNING SCREEN\'S OWN SAVE (save_morning), day by day,\n    for the patient slips his page showed saved, and the not-filled ones he chose to fill: a slip\'s earlier record is voided (kept),\n    an unchanged one is not written. No commit. Returns the words (English); refusals raise ValueError (English)."""\n    who = _who() if who is None else who\n    posted = [x for x in (form.getlist("refs") if hasattr(form, "getlist") else (form.get("refs") or [])) if x]\n    if not posted:\n        return "Nothing to save — no patient slip was changed or chosen."\n    lo, hi = max(morning_from(db), ym + "-01"), min(_today().isoformat(), _month_end(ym))\n    fs = fin_span(lo, hi)\n    if fs is None:\n        raise ValueError("The slip book could not be read just now.")\n    day_of = {s["ref"]: s["day"] for s in fs}\n    byday = {}\n    for r in posted:\n        if r in day_of:\n            byday.setdefault(day_of[r], []).append(r)\n    before = {r: (saved_use(db, r)[0] or {}).get("id") for r in posted}\n    for day in sorted(byday):\n        try:\n            save_morning(db, day, _DayForm(form, byday[day]), who)\n        except ValueError as e:\n            t = str(e)\n            m = re.search(r"Slip (\\d+)", t)\n            what = next((en for hi_, en in SAVE_WORDS if hi_ in t), "an item could not be read")\n            raise ValueError(("Patient slip %s: %s." % (m.group(1), what)) if m else (what[0].upper() + what[1:] + "."))\n    n = len([r for r in posted if (saved_use(db, r)[0] or {}).get("id") != before.get(r)])\n    if not n:\n        return "Nothing changed."\n    return "Saved — %d patient slip%s changed; the earlier entr%s stay%s in the record." % (n, "" if n == 1 else "s", "y" if n == 1 else "ies",\n                                                                                          "s" if n == 1 else "")\n\n\n\n# ---------------------------------------------------------------------------------------------- the owner\'s page\n'), ('E7 slip_post says dealer challan', '        msg = add_slip(db, f.get("day"), f.get("supplier"), f.get("note"), lines, f.get("paper") or "")\n', '        msg = add_slip(db, f.get("day"), f.get("supplier"), f.get("note"), lines, f.get("paper") or "")\n        msg = msg.replace("Slip of ", "Dealer challan of ", 1)                  # S831: Yuvika\'s papers are dealer challans on his page\n'), ('E8 void_post says dealer challan', 'flash("Photo slip voided — kept in the record, it counts nothing." if n else "That slip was not found or is already voided — nothing changed.")', 'flash("Dealer challan from a photo voided — kept in the record, it counts nothing." if n else "That dealer challan was not found or is already voided — nothing changed.")'), ("E10 the month Save's door", '    app.add_url_rule("/procroom/count", "s637_count", ar.owner_required(count_post), methods=["POST"])\n', '    app.add_url_rule("/procroom/count", "s637_count", ar.owner_required(count_post), methods=["POST"])\n    app.add_url_rule("/procroom/used", "s831_used", ar.owner_required(used_post), methods=["POST"])                 # S831: his month Save\n')]

BLOCKS = [("B1 his page's template", 'PAGE_TPL = """<style>\n#s634 details.card', 'MONTH_TPL = """<style>', 'PAGE_TPL = """<style>\n#s831{max-width:1180px;margin:0 auto;display:flex;flex-direction:column;gap:18px}\n#s831 h2.t{margin:0;font-size:26px}\n#s831 .tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px}\n#s831 a.tile{display:flex;flex-direction:column;gap:4px;padding:14px 16px;border-radius:12px;text-decoration:none;color:#1f2733;border:1px solid #e3e6ea;background:#fff;min-height:44px}\n#s831 a.tile:hover{border-color:#1d5fa8}\n#s831 .tl{font-size:13px;font-weight:600;color:#4a5361;text-transform:uppercase}#s831 .tb{font-size:26px;font-weight:700}#s831 .ts{font-size:13px;color:#4a5361}\n#s831 .red{color:#b42318;font-weight:700}#s831 .amb{color:#92400e}#s831 .muted{color:#4a5361}\n#s831 section.box{background:#fff;border:1px solid #e3e6ea;border-radius:12px;padding:18px;display:flex;flex-direction:column;gap:12px}\n#s831 section.box h3{margin:0;font-size:19px}\n#s831 .steps{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:14px}\n#s831 .step{border:2px solid #c9ced6;border-radius:10px;padding:14px;display:flex;flex-direction:column;gap:8px}\n#s831 .step.no{border-color:#c2410c;background:#fff7f2}#s831 .step.wait{border-color:#b45309;background:#fffbeb}#s831 .step.ok{border-color:#15803d;background:#f0fdf4}\n#s831 .sl{font-size:13px;font-weight:700}#s831 .sh{font-size:17px;font-weight:600}\n#s831 table{border-collapse:collapse;width:100%}#s831 td,#s831 th{text-align:left;padding:7px 9px;border-bottom:1px solid #e3e6ea;vertical-align:top}\n#s831 th{font-size:13px;color:#4a5361;background:#f7f8fa}#s831 .r{text-align:right}\n#s831 details{background:#fff;border:1px solid #e3e6ea;border-radius:10px}\n#s831 details>summary{cursor:pointer;font-weight:600;font-size:16px;padding:12px 14px}\n#s831 .in{padding:0 14px 14px;display:flex;flex-direction:column;gap:10px}\n#s831 .fy{display:grid;grid-template-columns:1.3fr repeat(5,1fr);gap:8px}\n#s831 summary .fy{display:inline-grid;width:calc(100% - 24px);vertical-align:top}\n#s831 .fyh{padding:0 14px;font-size:13px;font-weight:600;color:#4a5361}#s831 .fyt{padding:10px 14px;border-top:2px solid #c9ced6;font-weight:700}\n#s831 input.qty{width:68px;text-align:right}\n#s831 .kit{display:flex;flex-wrap:wrap;gap:6px 16px;align-items:center;font-size:14px}\n#s831 .kit label{display:inline-flex;gap:6px;align-items:center;margin:0;font-weight:normal}#s831 .kit input[type=checkbox]{width:auto;margin:0}\n#s831 tr.nf td{background:#fffbeb}#s831 details.sub{border-color:#dbe3ec}#s831 details.sub>summary{font-size:15px}\n#s831 details.plain{border:0;background:transparent}#s831 details.plain>summary{font-size:13px;font-weight:400;padding:4px 0}\n#s831 input.rt{max-width:90px;min-width:72px}#s831 .s634v{opacity:.55}#s831 .okw{color:#0e5a45}\na.s831top{position:fixed;right:22px;bottom:22px;background:#1d5fa8;color:#fff;text-decoration:none;font-weight:600;font-size:15px;padding:12px 16px;border-radius:24px;box-shadow:0 2px 8px rgba(0,0,0,.2);z-index:50}\n</style>\n{% macro kit(s, pre) %}<div class=kit>{% for l in s.kit %}{% set f = pre ~ l.key %}\n{% if l.proc and (loop.first or s.kit[loop.index0 - 1].proc != l.proc) %}<span style="flex-basis:100%;font-weight:600;font-size:13px">{{l.proc}}</span>{% endif %}\n{% if l.ask == \'size_qty\' and l.sizes %}<label>{{l.item}} <select name="{{f}}_s" aria-label="Size of {{l.item}}"><option value="">—</option>{% for z in l.sizes %}<option value="{{z.size}}"{{\' selected\' if z.size == l.size}}>{{z.size}}</option>{% endfor %}</select> × <input class=qty name="{{f}}_q" value="{{l.qty}}" inputmode=decimal aria-label="How many {{l.item}}"></label>\n{% elif l.ask == \'one_of\' %}<label>{{l.item}} <select name="{{f}}_o" aria-label="{{l.item}}"><option value="">—</option>{% for c in l.choices %}<option value="{{c.name}}"{{\' selected\' if c.name == l.choice}}>{{c.name}}</option>{% endfor %}</select></label>\n{% else %}<label><input type=checkbox name="{{f}}_c" value=1{{\' checked\' if l.on}}> {{l.item}}</label>{% endif %}{% endfor %}\n{% if s.gloves %}<span class=muted>Gloves {{pairs(s.gloves)}} (your allowance)</span>{% endif %}{% if not s.kit %}<span class=muted>No set items for this procedure.</span>{% endif %}</div>\n<details class=plain><summary>+ Add an item</summary><div class=kit>{% for k in range(1, 4) %}{% set a = s.added[k-1] if s.added|length >= k else none %}<label><select class=s831add name="{{pre}}a{{k}}_i" data-sel="{{a.item_id if a else \'\'}}" aria-label="Item to add">{% if a %}<option value="{{a.item_id}}" selected>{{a.iname}}</option>{% else %}<option value="">—</option>{% endif %}</select> × <input class=qty name="{{pre}}a{{k}}_q" value="{{plain(a.qty) if a else \'\'}}" inputmode=decimal aria-label="How many"></label>{% endfor %}</div></details>{% endmacro %}\n<div id=s831>\n<div style="display:flex;flex-wrap:wrap;align-items:baseline;justify-content:space-between;gap:12px">\n<h2 class=t>Procedure room</h2>\n<form method=get action="{{url_for(\'s634_page\')}}" style="display:flex;gap:6px;align-items:center;margin:0"><label for=s831mo style="margin:0">Month</label><input id=s831mo type=month name=ym value="{{m.ym}}" max="{{this_ym}}" style="max-width:170px"><button class=btn>Show</button></form>\n</div>\n<nav class=tiles aria-label="At a glance" id=s831tiles>\n<a class=tile href="#m{{m.ym}}" data-t=spent style="background:#eef4fb;border-color:#c8d9ee"><span class=tl>Spent {{\'this month\' if m.ym == this_ym else \'in \' ~ m.label}}</span><span class=tb>{{rs(m.cur.bought)}}</span><span class=ts>{{m.cur.nch}} dealer challan{{\'\' if m.cur.nch == 1 else \'s\'}} counted</span></a>\n<a class=tile href="#m{{m.ym}}" data-t=rev style="background:#eefaf2;border-color:#c5e8d0"><span class=tl>Procedure revenue</span>{% if m.cur.procs is not none %}<span class=tb>{{rs(m.cur.ili + m.cur.other)}}</span><span class=ts>ILI {{rs(m.cur.ili)}} · others {{rs(m.cur.other)}}</span>{% else %}<span class=tb>—</span><span class=ts>{{\'the slip book could not be read\' if not m.book_ok else \'counted from \' ~ dmy(m.floor)}}</span>{% endif %}</a>\n<a class=tile href="#m{{m.ym}}" data-t=done><span class=tl>Procedures done</span><span class=tb>{{m.cur.procs if m.cur.procs is not none else \'—\'}}</span><span class=ts>{{m.cur.cast_n}} casts / slabs · {{m.cur.ili_n}} ILI · {{m.cur.other_n}} other</span></a>\n<a class=tile href="#s637stock" data-t=fib style="background:#fff7f2;border-color:#f5cdb5"><span class=tl style="color:#9a3412">Fibrecast in stock today</span>\n<span style="display:grid;grid-template-columns:auto auto;gap:2px 12px;font-size:16px;align-items:baseline">{% for f in m.fib %}<span>{{f.size}}</span><span style="text-align:right;font-weight:700" class="{{\'red\' if f.red}}" data-fib="{{f.size}}">{{f.word}}</span>{% endfor %}</span>\n<span class=ts style="color:#9a3412">{% if not m.fib_counted %}after your first count · {% endif %}a size under its reorder level turns red</span></a>\n<a class=tile href="#s831start" data-t=wait style="background:#fffbeb;border-color:#f3e0a6"><span class=tl style="color:#92400e">Waiting for you</span><span class=tb>{{m.wait_n}}</span><span class=ts style="color:#92400e">{{m.wait_words}}</span></a>\n<a class=tile href="#s831start" data-t=morning><span class=tl>Morning screen</span><span class=tb>{{m.mo.n if m.mo.n is not none else \'—\'}}</span><span class=ts>{{m.mo.words}}</span></a>\n</nav>\n<section class=box id=s831start aria-labelledby=s831sh><h3 id=s831sh>Start here — three steps keep the stock correct</h3><div class=steps>\n<div class="step {{\'ok\' if m.s1.done else \'no\'}}" data-step=1><div class=sl>STEP 1 · {{\'DONE\' if m.s1.done else \'NOT DONE\'}}</div><div class=sh>Opening count — once</div>\n<div>{% if m.s1.done %}Counted.{% if m.s1.missing %} {{m.s1.missing}} product{{\'\' if m.s1.missing == 1 else \'s\'}} in use without a count yet.{% else %} Every product in use has a count.{% endif %}{% else %}Count what is on the shelf and type it. From then on the page keeps the stock by itself.{% endif %}</div>\n<a class=btn href="#s637stock" style="align-self:flex-start">{{\'Count the shelf now\' if not m.s1.done else \'Stock now\'}}</a></div>\n<div class="step {{\'wait\' if m.s2.n else \'ok\'}}" data-step=2><div class=sl>STEP 2 · {{(m.s2.n ~ \' WAITING\') if m.s2.n else \'NOTHING WAITING\'}}</div><div class=sh>Purchases — Yuvika\'s dealer challans</div>\n<ul style="margin:0;padding-left:18px">{% for p in m.s2.papers %}<li data-wait="{{p.id}}"><a href="{{href(p.id)}}">{{p.stamp}}</a> dealer challan {{dmy(p.day)[:5]}} — on the desk, lines not saved</li>{% endfor %}{% for p in m.s2.photos %}<li data-wphoto="{{p.id}}"><a href="{{url_for(\'s635_month\', ym=p.ym, photo=p.id)}}#s635edit">Yuvika\'s {{p.mlabel}} photo</a> — {{p.state}}</li>{% endfor %}{% if not m.s2.n %}<li>Every dealer challan on the desk has its lines saved.</li>{% endif %}</ul>\n<div style="display:flex;gap:8px;flex-wrap:wrap"><a class=btn href="{{desk}}">Open on the desk</a><a class=btn href="{{url_for(\'s635_month\', ym=m.ym)}}">Yuvika\'s month photo</a></div></div>\n<div class="step {{\'ok\' if m.s3.on else \'wait\'}}" id=s637card data-step=3><div class=sl>STEP 3 · {{\'RUNNING\' if m.s3.on else \'OFF FOR THE STAFF\'}}</div><div class=sh>Used — Shavez\'s morning screen</div>\n<div>{{\'On.\' if m.s3.on else \'Off for the staff — you see it first.\'}} Each patient\'s procedure items are noted the next morning; you can correct them below, under each month.{% if m.s3.behind %} {{m.s3.behind}} patient slip{{\'\' if m.s3.behind == 1 else \'s\'}} still to fill.{% endif %}</div>\n<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center"><a class=btn href="{{url_for(\'s637_morning\')}}">Open Kal ke procedures</a><form method=post action="{{url_for(\'s637_switch\')}}" style="margin:0"><input type=hidden name=back value="{{back}}"><input type=hidden name=to value="{{\'off\' if m.s3.on else \'on\'}}"><button class="btn small">{{\'Switch off\' if m.s3.on else \'Switch on for Shavez\'}}</button></form></div></div>\n</div></section>\n<section class=box id=s831fy aria-labelledby=s831fh><h3 id=s831fh>Expenses and revenue — financial year {{m.fy}}-{{\'%02d\' % ((m.fy + 1) % 100)}}</h3>\n<div class=muted style="font-size:14px">Bought = Yuvika\'s dealer challans and bills of the month at your rates, each rupee once (home use, clinic equipment, OT and orthotics apart). Revenue = the patient slips of the month with a procedure, ILI apart from the other procedures. Open a month to see what was bought and each procedure done.</div>\n{% if not m.book_ok %}<div class=red>The slip book could not be read just now — procedures and revenue show “—”.</div>{% endif %}\n<div class="fy fyh"><span>Month</span><span class=r>Bought ₹</span><span class=r>Procedures</span><span class=r>ILI revenue ₹</span><span class=r>Other procedures ₹</span><span class=r>Revenue less bought ₹</span></div>\n{% for x in m.months|reverse %}<details id="m{{x.ym}}" data-ym="{{x.ym}}"{{\' open\' if x.ym == m.ym}}><summary><span class=fy><span>{{x.short}}{% if x.wait %} <span style="font-weight:400;font-size:13px;color:#b45309">{{x.wait}}</span>{% endif %}</span><span class=r>{{n(x.bought)}}</span><span class=r>{{x.procs if x.procs is not none else \'—\'}}</span><span class=r>{{n(x.ili)}}</span><span class=r>{{n(x.other)}}</span><span class=r>{{n(x.less)}}</span></span></summary>\n<div class=in>\n<details class=sub open><summary>What was bought — dealer challans and bills <span class=muted style="font-weight:400">({{x.bwords}})</span></summary><div class=in style="overflow-x:auto">\n{% if x.lines or x.waiting %}<table><tr><th>Dealer challan</th><th>Date</th><th>Item</th><th class=r>Qty</th><th class=r>Rate ₹</th><th class=r>Amount ₹</th></tr>\n{% for l in x.lines %}<tr data-line="{{l.id}}"><td>{% if l.bid %}<a href="{{href(l.bid)}}">{{l.stamp}}</a>{% else %}from a photo{% endif %} {{l.vendor}}</td><td>{{dmy(l.when)[:5]}}</td><td>{{l.name}}{% if l.brand %} · {{l.brand}}{% endif %}</td><td class=r>{{q(l.qty)}} {{l.unit}}</td><td class=r>{{n(l.eff)}}</td><td class=r>{{n(l.amt)}}</td></tr>{% endfor %}\n{% for p in x.waiting %}<tr data-waiting="{{p.id}}"><td><a href="{{href(p.id)}}">{{p.stamp}}</a> {{p.vendor}}</td><td>{{dmy(p.day)[:5]}}</td><td colspan=4 class=amb>not saved on the desk yet</td></tr>{% endfor %}</table>\n{% else %}<p class=muted style="margin:0">Nothing bought for the procedure room in {{x.label}}.</p>{% endif %}\n{% if x.else_n %}<p class=muted style="margin:0">Kept elsewhere on these dealer challans: {{x.else_n}} line{{\'\' if x.else_n == 1 else \'s\'}}, {{rs(x.else_amt)}} (home use, clinic equipment, OT, orthotics) — not in Bought.</p>{% endif %}\n</div></details>\n{% if x.before %}<p class=muted style="margin:0">Procedures are counted from {{dmy(m.floor)}}, when the morning screen began; before that only what was bought is known.</p>\n{% elif x.procs is none %}<p class=red style="margin:0">The slip book could not be read just now.</p>\n{% else %}<details class=sub open><summary>Procedures done — {{x.procs}} <span class=muted style="font-weight:400">(each patient\'s items: correct or add, then save)</span></summary>\n<form method=post action="{{url_for(\'s831_used\')}}" class=in data-month="{{x.ym}}"><input type=hidden name=ym value="{{x.ym}}"><div style="overflow-x:auto"><table><tr><th>Date</th><th>Patient slip</th><th>Patient</th><th>Procedure</th><th class=r>Fee ₹</th><th>Items used</th></tr>\n{% for s in x.slips %}{% set pre = \'u\' ~ s.id ~ \'_\' %}<tr data-pslip="{{s.no}}" class="{{\'\' if s.saved else \'nf\'}}"><td>{{dmy(s.day)[:5]}}</td><td>{{s.no}}</td><td>{{s.name}}{% if s.last4 %} <span class=muted>…{{s.last4}}</span>{% endif %}</td><td>{{s.procs|join(\' + \')}}</td><td class=r>{{n(s.fee)}}</td><td>\n{% if s.saved %}<div class=chg><input type=checkbox name=refs value="{{s.ref}}" class=fillref hidden aria-hidden=true tabindex=-1>{{ kit(s, pre) }}</div>{% else %}<details class="plain fill"><summary class=amb>not filled yet — fill here or leave for Shavez</summary><label style="font-size:13px;margin:4px 0;display:inline-flex;gap:6px;align-items:center"><input type=checkbox name=refs value="{{s.ref}}" class=fillref style="width:auto;margin:0"> save these items for this patient slip</label>{{ kit(s, pre) }}</details>{% endif %}\n</td></tr>{% endfor %}\n{% if not x.slips %}<tr><td colspan=6 class=muted>No patient slip with a procedure in {{x.label}}.</td></tr>{% endif %}</table></div>\n{% if x.slips %}<button class=btn style="align-self:flex-start">Save the changes</button>{% endif %}\n<div class=muted style="font-size:13px">Only the patient slips you change are saved; your change replaces Shavez\'s entry for that slip, and his stays in the record. Totals: ILI {{x.ili_n}} · {{rs(x.ili)}} · other procedures {{x.cast_n + x.other_n}} · {{rs(x.other)}}.{% if x.nahi %} {{x.nahi}} patient slip{{\'\' if x.nahi == 1 else \'s\'}} Docterz did not have (not done) left out.{% endif %}</div>\n</form></details>{% endif %}\n</div></details>{% endfor %}\n<div class="fy fyt" id=s831year><span>Year so far</span><span class=r>{{n(m.year.bought)}}</span><span class=r>{{m.year.procs if m.year.procs is not none else \'—\'}}</span><span class=r>{{n(m.year.ili)}}</span><span class=r>{{n(m.year.other)}}</span><span class=r>{{n(m.year.less)}}</span></div>\n<div class=muted style="font-size:13px">Procedures and revenue are counted from {{dmy(m.floor)}}, when the morning screen began; before that only what was bought is known.</div>\n</section>\n<section class=box id=s637stock aria-labelledby=s831stk><div style="display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px;align-items:baseline"><h3 id=s831stk>Stock now</h3><div class=muted style="font-size:14px">Stock = your count + bought since − used since</div></div>\n<form method=post action="{{url_for(\'s637_count\')}}" style="display:flex;flex-direction:column;gap:10px;margin:0"><input type=hidden name=back value="{{back}}">\n<div style="overflow-x:auto"><table><tr><th>Product</th><th class=r>Your count</th><th class=r>+ Bought since</th><th class=r>− Used since</th><th class=r>Stock now</th><th class=r>Order when below</th><th>Day of the count</th></tr>\n{% for s in m.stock %}<tr data-stock="{{s.id}}"><td>{{s.name}}{% if s.gloves %} <span class=muted style="font-size:13px">(box of {{m.gl.box_word}})</span>{% endif %}</td>\n<td class=r><input class=qty name="c{{s.id}}" inputmode="{{\'numeric\' if s.gloves else \'decimal\'}}" placeholder="{{s.ph}}" aria-label="Count of {{s.name}}"></td>\n<td class=r>{{s.bought}}</td><td class=r>{{s.used}}</td><td class="r{{\' red\' if s.red}}">{{s.stock}}</td>\n<td class=r><input type=hidden name="w{{s.id}}" value="{{s.reorder}}"><input class=qty name="o{{s.id}}" value="{{s.reorder}}" inputmode="{{\'numeric\' if s.gloves else \'decimal\'}}" placeholder="set" aria-label="Order {{s.name}} when below"></td><td class=muted>{{s.day}}{% if s.last %} · {{s.last}}{% endif %}</td></tr>{% endfor %}</table></div>\n<div style="display:flex;flex-wrap:wrap;gap:12px;align-items:center"><label style="margin:0">Day of the count <input name=day value="{{dmy(today_iso)}}" style="max-width:130px"></label><button class=btn>Save the counts</button></div></form>\n<div class=muted style="font-size:14px;border-top:1px solid #e3e6ea;padding-top:10px" id=s831gloves>Gloves: <b>{{m.gl.cast}} pair{{\'\' if m.gl.cast == \'1\' else \'s\'}}</b> a cast or slab · <b>{{m.gl.ili}}</b> an ILI · box of <b>{{m.gl.box_word}}</b> <a href="#s634list" onclick="var d=document.getElementById(\'s634list\');if(d){d.open=true;}">change</a></div></section>\n<div style="display:flex;flex-direction:column;gap:10px"><div class=muted style="font-size:14px;padding-left:4px">More — folded until you need them</div>\n<details id=s637match><summary>Month-end match — what was bought per 10 procedures</summary><div class=in>\n<p style="margin:0">{{v.label}}: casts and slabs <b>{{v.done.cast}}</b> · injections (ILI) <b>{{v.done.ili}}</b> · other procedures <b>{{v.done.other}}</b> <span class=muted>(from Shavez\'s morning screen)</span></p>\n{% if v.match %}<div style="overflow:auto"><table><tr><th>Product (counted at month end)</th><th class=r>Bought</th><th class=r>Per 10 procedures</th><th class=r>This financial year, per 10</th></tr>\n{% for x in v.match %}<tr><td>{{x.name}}</td><td class=r>{{q(x.bought)}} {{x.unit}}</td><td class=r>{{\'%.1f\' % x.per10 if x.per10 is not none else \'—\'}}</td><td class=r>{{\'%.1f\' % x.fy10 if x.fy10 is not none else \'—\'}}</td></tr>{% endfor %}</table></div>\n<p class=muted style="margin:0">A rough match: what was bought for every ten procedures done. A month far from the year\'s figure is worth a look.</p>{% else %}<p class=muted style="margin:0">Nothing counted at month end was bought in {{v.label}}.</p>{% endif %}</div></details>\n<details id=s634slips><summary>Dealer challans and their rates — {{v.label}} ({{v.slips|length}})</summary><div class=in>\n<p class=muted style="margin:0">Type or correct the rate on any line, then Save that dealer challan. A blank rate is “no rate yet”. The rate read from a printed bill shows in grey until you type your own.</p>\n{% for s in v.slips %}<form method=post action="{{url_for(\'s634_rates\')}}" class=s634slip data-slip="{{s.key}}" style="border:1px solid #dde3ea;border-radius:10px;padding:8px 12px;margin:0">\n<input type=hidden name=back value="{{back}}"><div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:6px"><b>{{dmy(s.when)}} · {{s.vendor or \'supplier not read\'}} · {% if s.src == \'paper\' %}<a href="{{href(s.bid)}}">{{s.stamp}}</a>{% else %}from a photo only{% if s.note %} — {{s.note}}{% endif %}{% endif %}</b><span>{{rs(s.total)}}{% if s.norate %} <span class="badge amber">{{s.norate}} without a rate</span>{% endif %}</span></div>\n<div style="overflow:auto"><table><tr><th>Product</th><th>Brand</th><th class=r>Qty</th><th>Place</th><th>Rate ₹</th><th class=r>Amount</th></tr>\n{% for l in s.lines %}<tr><td>{{l.name}}{% if l.ask %} <span class="badge amber">not on your list</span>{% endif %}</td><td>{{l.brand}}</td><td class=r>{{q(l.qty)}} {{l.unit}}</td><td>{{l.place}}</td>\n<td><input class=rt name="r{{l.id}}" value="{{plain(l.rate)}}" inputmode=decimal placeholder="{{plain(l.rate_read) if l.rate_read is not none else \'\'}}" aria-label="Rate of {{l.name}}"></td><td class=r>{{rs(l.amt) if l.amt is not none else \'—\'}}</td></tr>{% endfor %}</table></div>\n<div style="display:flex;gap:8px;align-items:center;margin-top:6px"><button class=btn>Save the rates</button></div></form>\n{% if s.src == \'photo\' %}<form method=post action="{{url_for(\'s634_void\')}}" style="margin:-4px 0 4px" onsubmit="return confirm(\'Void this dealer challan from a photo? It stays in the record, struck through, and counts nothing.\')"><input type=hidden name=slip value="{{s.sid}}"><input type=hidden name=back value="{{back}}"><button class="btn small danger">Void this dealer challan from a photo</button></form>{% endif %}\n{% endfor %}{% if not v.slips %}<p class=muted style="margin:0">None for {{v.label}}.</p>{% endif %}</div></details>\n<details id=s635orders{{\' open\' if v.orders|selectattr(\'state\', \'equalto\', \'awaiting\')|list}}><summary>Your orders and deliveries — {{v.label}}</summary><div class=in>\n{% if v.orders or v.noorder %}<div style="overflow:auto"><table><tr><th>Your order</th><th>Day</th><th>What</th><th>Dealer challans against it</th><th>State</th></tr>\n{% for o in v.orders %}<tr data-order="{{o.id}}"><td><a href="{{href(o.id)}}">{{o.stamp}}</a>{% if o.book %} <span class=muted>book {{o.book}}</span>{% endif %}</td><td>{{dmy(o.day)}}</td>\n<td class=muted>{% for l in o.lines %}{{l.name}} {{q(l.qty)}}{{\', \' if not loop.last}}{% else %}no lines yet{% endfor %}</td>\n<td>{% for s in o.slips %}<a href="{{href(s.id)}}">{{s.stamp}}</a> <span class=muted>{{dmy(s.day)[:5]}}</span>{{\' · \' if not loop.last}}{% else %}—{% endfor %}</td>\n<td>{% if o.state == \'awaiting\' %}<span class="badge amber">awaiting — {{o.age}} days</span>{% elif o.state == \'ordered\' %}ordered{% if o.age is not none %} {{o.age}} day{{\'\' if o.age == 1 else \'s\'}} ago{% endif %}{% elif o.state == \'part\' %}<span class="badge amber">part came</span>{% else %}delivered{% endif %}{% for x in o.diffs %}<div class=muted>{{x}}</div>{% endfor %}</td></tr>{% endfor %}\n{% for s in v.noorder %}<tr data-noorder="{{s.id}}"><td><span class="badge amber">no order</span></td><td>{{dmy(s.day)}}</td><td colspan=3><a href="{{href(s.id)}}">{{s.stamp}}</a> — no order of yours is joined to this dealer challan. Join it on the desk, or leave it.</td></tr>{% endfor %}\n</table></div>{% else %}<p class=muted style="margin:0">No order of yours for {{v.label}}. When your signed order page is sorted on the desk into Procedure room, choose “Dr Manoj\'s order”; the dealer challan that comes against it is joined to it there.</p>{% endif %}\n<p class=muted style="margin:0">An order with no dealer challan after {{v.await}} days shows “awaiting” (change the days under Your product list and allowances).{% if v.floor %} Dealer challans scanned before {{dmy(v.floor[:10])}} are never called “no order”.{% endif %}</p></div></details>\n<details id=s634add><summary>+ Add a dealer challan from a photo by hand</summary>\n<form method=post action="{{url_for(\'s634_slip\')}}" class=in><input type=hidden name=back value="{{back}}">\n<div style="display:flex;flex-wrap:wrap;gap:8px;align-items:flex-end"><label style="margin:0">Date<input name=day placeholder="dd-mm-yyyy" style="max-width:130px" required></label>\n<label style="margin:0">Supplier<input name=supplier value="{{supplier}}" style="max-width:200px"></label><label style="margin:0">Note<input name=note style="max-width:220px" placeholder="e.g. from the WhatsApp of 30-09"></label>\n<label style="margin:0">Scanned as (if on the desk)<input name=paper placeholder="B-0007" style="max-width:110px"></label></div>\n<div style="overflow:auto"><table><tr><th>Product</th><th>or what it is</th><th>Brand</th><th>Qty</th><th>Place</th><th>Rate ₹</th></tr>\n{% for k in range(1, 9) %}<tr><td><select name="i{{k}}" style="max-width:220px"><option value="">—</option>{% for i in v.products if i.state != \'retired\' %}<option value="{{i.id}}">{{i.name}}</option>{% endfor %}</select></td>\n<td><input name="n{{k}}" style="max-width:170px"></td><td><input name="b{{k}}" style="max-width:110px"></td><td><input name="q{{k}}" inputmode=decimal style="max-width:70px"></td>\n<td><select name="p{{k}}">{% for pk, pw in places_list %}<option value="{{pk}}">{{pw}}</option>{% endfor %}</select></td><td><input name="r{{k}}" inputmode=decimal style="max-width:90px"></td></tr>{% endfor %}</table></div>\n<p class=muted style="margin:0">A Procedure room line takes a product from your list; a line kept elsewhere (home use, clinic equipment, OT, Sanjeevni) may be typed by its name. With “Scanned as”, the lines go onto that dealer challan instead (it must be in Procedure room on the desk).</p>\n<button class="btn small" style="align-self:flex-start">Save the dealer challan</button></form></details>\n<details id=s634list><summary>Your product list and allowances</summary><div class=in>\n<form method=post action="{{url_for(\'s634_allow\')}}" style="display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:0" id=s634allow><input type=hidden name=back value="{{back}}">\n<b>Examination gloves:</b> <input name=cast value="{{allow[\'proc.gloves_cast\']}}" inputmode=decimal style="max-width:50px" aria-label="Pairs a cast or slab"> pairs a cast or slab ·\n<input name=ili value="{{allow[\'proc.gloves_ili\']}}" inputmode=decimal style="max-width:50px" aria-label="Pairs an ILI"> pairs an ILI · a box holds <input name=box value="{{allow[\'proc.gloves_box\']}}" inputmode=decimal style="max-width:60px" placeholder="50" aria-label="Pairs in a box"> pairs ·\n<b>An order is late after</b> <input name=await value="{{allow[\'proc.await_days\']}}" inputmode=decimal style="max-width:50px" aria-label="Days before an order is awaiting"> days\n<button class="btn small">Save</button></form>\n{% if v.asks %}<div id=s634asks><b>Waiting for your list</b> <span class=muted>— lines the desk marked “not on the list”. Add the product below; then sort the dealer challan again on the desk.</span>\n<ul style="margin:4px 0 0">{% for d in v.asks %}<li>{{d.name}} · {{q(d.qty)}} {{d.unit}} · {% if d.stamp %}<a href="{{href(d.bill_id)}}">{{d.stamp}}</a>{% else %}from a photo {{dmy(d.when)}}{% endif %}</li>{% endfor %}</ul></div>{% endif %}\n<form method=post action="{{url_for(\'s634_item\')}}" style="display:flex;flex-wrap:wrap;gap:6px;align-items:flex-end;margin:0"><input type=hidden name=do value=add><input type=hidden name=back value="{{back}}">\n<label style="margin:0">Product (what and size)<input name=name required style="max-width:220px"></label><label style="margin:0">Unit<input name=unit list=s634units value=piece style="max-width:90px"></label>\n<label style="margin:0">Counted<select name=how>{% for k, w in hows %}<option value="{{k}}"{{\' selected\' if k == \'match\'}}>{{w}}</option>{% endfor %}</select></label>\n<label style="margin:0">Brands<input name=brands style="max-width:150px" placeholder="Gloster, Duracast"></label><label style="margin:0">Other spellings<input name=aliases style="max-width:200px"></label>\n<label style="margin:0">Reorder below<input name=reorder inputmode=decimal style="max-width:70px"></label><button class="btn small">+ Add</button></form>\n<datalist id=s634units>{% for u in units %}<option value="{{u}}">{% endfor %}</datalist>\n{% for i in v.products %}<form method=post action="{{url_for(\'s634_item\')}}" style="display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:0" class="{{\'s634v\' if i.state == \'retired\'}}"><input type=hidden name=id value="{{i.id}}"><input type=hidden name=back value="{{back}}">\n<input name=name value="{{i.name}}" style="max-width:220px" aria-label="Name"><input name=unit value="{{i.unit}}" list=s634units style="max-width:80px" aria-label="Unit">\n<select name=how aria-label="Counted">{% for k, w in hows %}<option value="{{k}}"{{\' selected\' if k == i.how}}>{{w}}</option>{% endfor %}</select>\n<input name=brands value="{{i.brands}}" style="max-width:150px" placeholder="brands" aria-label="Brands"><input name=aliases value="{{i.aliases}}" style="max-width:200px" placeholder="other spellings" aria-label="Other spellings">\n<input name=reorder value="{{plain(i.reorder)}}" inputmode=decimal style="max-width:70px" placeholder="reorder" aria-label="Reorder below">\n<button class="btn small" name=do value=edit>Save</button>\n{% if i.state == \'active\' %}<button class="btn small" name=do value=rare>Rarely used</button>{% endif %}{% if i.state != \'active\' %}<button class="btn small" name=do value=restore>In use</button>{% endif %}\n{% if i.state != \'retired\' %}<button class="btn small" name=do value=retire>Retire</button>{% endif %}<span class=muted>{{states[i.state]}}</span></form>{% endfor %}\n<p class=muted style="margin:0">A product with lines is never deleted — retire it. Other spellings help the desk pre-choose a product from what the reader made of the handwriting. The gloves\' reorder level here is in boxes; in Stock now it is in pairs.</p></div></details>\n</div>\n</div>\n<a href="#s831" class=s831top aria-label="Back to top">↑ Top</a>\n<script>(function(){var IT={{m.items_json|safe}};\nfunction fill(sel){if(sel.getAttribute(\'data-filled\')){return;}var cur=sel.getAttribute(\'data-sel\')||\'\';sel.innerHTML=\'\';var o=document.createElement(\'option\');o.value=\'\';o.textContent=\'—\';sel.appendChild(o);\nIT.forEach(function(x){var p=document.createElement(\'option\');p.value=String(x[0]);p.textContent=x[1];if(String(x[0])===cur){p.selected=true;}sel.appendChild(p);});sel.setAttribute(\'data-filled\',\'1\');}\ndocument.querySelectorAll(\'#s831 details.plain\').forEach(function(d){d.addEventListener(\'toggle\',function(){if(d.open){d.querySelectorAll(\'select.s831add\').forEach(fill);}});});\ndocument.querySelectorAll(\'#s831 details.fill, #s831 div.chg\').forEach(function(d){var cb=d.querySelector(\'input.fillref\');d.addEventListener(\'change\',function(e){if(cb&&e.target!==cb){cb.checked=true;}});});\n})();</script>"""\n\n'), ('B2 page_view', 'def page_view():\n', '\n\ndef item_post():', 'def page_view():\n    """S831: his simplified page (D982) -- the month picker, the tiles, Start here, the financial year (X-ray page style), Stock now\n    and the rest folded. ?fy=YYYY (an older link) opens that financial year at its last month."""\n    db = AR.get_db()\n    ym, fy = request.args.get("ym") or None, request.args.get("fy") or None\n    if ym and not (re.fullmatch(r"\\d{4}-(0[1-9]|1[0-2])", ym)):\n        ym = None\n    if not ym and fy and str(fy).isdigit() and 2020 <= int(fy) <= _today().year:\n        ym = min(fy_months(int(fy))[-1], _ym())\n    back = ("ym=%s" % ym) if ym else ""\n    m = page_model(db, ym or _ym())\n    allow = {k: (_setting(db, k, d) or "") for k, d in ALLOW}\n    desk = url_for("s551_desk") if "s551_desk" in AR.app.view_functions else url_for("bills_list")\n    return AR.page(PAGE_TPL, m=m, v=m["v"], this_ym=_ym(), today_iso=_today().isoformat(), rs=rs, n=_n, pairs=pairs_word,\n                   q=lambda x: _plain(x) if x is not None else "—", plain=_plain, dmy=_dmy, href=_href, desk=desk,\n                   places=PLACE_WORD, places_list=PLACES, hows=HOW, states=STATE_WORD, units=UNITS, allow=allow, back=back, supplier=SUPPLIER,\n                   flow=AR._flow("Procedure room", url_for("s551_month") if "s551_month" in AR.app.view_functions else url_for("bills_list")))'), ('B3 count_post and used_post', 'def count_post():\n', '\n\ndef menu_items(role):', 'def count_post():\n    """His shelf counts and his reorder levels, from Stock now, in one Save. Gloves are typed in WHOLE PAIRS (never a decimal) and\n    kept in boxes of his box size (proc.gloves_box pairs); every other product in its own unit. A blank count is no count; a blank\n    reorder level clears it."""\n    db = AR.get_db()\n    items = {i["id"]: i for i in item_rows(db)}\n    box = _box(db)\n    counts, reos, bad = {}, {}, []\n    for k, v in request.form.items():\n        if not (k[:1] in ("c", "o") and k[1:].isdigit() and int(k[1:]) in items):\n            continue\n        s = str(v).strip()\n        if k[0] == "c" and not s:\n            continue\n        it = items[int(k[1:])]\n        if k[0] == "o" and _is_gloves(it) and not box:\n            continue                                                 # shown blank without a box size: never cleared by that blank\n        if k[0] == "o" and s == str(request.form.get("w" + k[1:], "\\x00")).strip():\n            continue                                                 # the level as shown, untouched: never rewritten by its rounding\n        n = _num(s) if s else None\n        if s and (n is None or n < 0):\n            bad.append("“%s” is not a number." % s[:20])\n            continue\n        if n is not None and _is_gloves(it):\n            if n != int(n):\n                bad.append("Gloves are counted in whole pairs — “%s” is not a whole number." % s[:20])\n                continue\n            if not box:\n                bad.append("Set how many pairs a box of gloves holds first (Your product list and allowances).")\n                continue\n            n = n / box\n        (counts if k[0] == "c" else reos)[it["id"]] = n\n    if bad:\n        flash(bad[0] + " Nothing was saved.")\n        return _go(_back(), "#s637stock")\n    try:\n        n = save_counts(db, request.form.get("day"), counts) if counts else 0\n        r = 0\n        for iid, val in reos.items():\n            old = items[iid]["reorder"]\n            if (old is None and val is None) or (old is not None and val is not None and round(old, 6) == round(val, 6)):\n                continue\n            db.execute("UPDATE proc_item SET reorder=? WHERE id=?", (val, iid))\n            _audit(db, "proc_reorder", {"id": iid, "from": old, "to": val})\n            r += 1\n        db.commit()\n        words = []\n        if n:\n            words.append("Counts saved (%d product%s)." % (n, "" if n == 1 else "s"))\n        if r:\n            words.append("Reorder levels saved (%d)." % r)\n        flash(" ".join(words) or "No count typed and no reorder level changed.")\n    except ValueError as e:\n        db.rollback()\n        flash(str(e) + " Nothing was saved.")\n    return _go(_back(), "#s637stock")\n\n\ndef used_post():\n    """S831: his one Save of a month\'s procedures (his page\'s Expenses and revenue, inside a month) -- through the morning screen\'s\n    own save, day by day (save_month)."""\n    db = AR.get_db()\n    ym = request.form.get("ym") or ""\n    if not re.fullmatch(r"\\d{4}-(0[1-9]|1[0-2])", ym):\n        ym = _ym()\n    try:\n        msg = save_month(db, ym, request.form)\n        db.commit()\n    except ValueError as e:\n        db.rollback()\n        msg = str(e) + " Nothing was saved."\n    flash(msg)\n    return redirect(url_for("s634_page", ym=ym) + "#m" + ym)')]



def apply(t, out=print):
    for name, old, new in EDITS:
        c = t.count(old)
        if c != 1:
            raise SystemExit("%s: found %d times, not once -- STOP" % (name, c))
        t = t.replace(old, new)
        out("  %s: 1 replacement" % name)
    for name, a, b, new in BLOCKS:
        if t.count(a) != 1 or t.count(b) != 1:
            raise SystemExit("%s: its start or end is not there exactly once -- STOP" % name)
        i = t.index(a)
        j = t.index(b, i)
        t = t[:i] + new + ("\n" if not new.endswith("\n") and b.startswith("MONTH") else "") + t[j:]
        out("  %s: 1 block (%d -> %d characters)" % (name, j - i, len(new)))
    return t


def build(src, dst, out=print):
    raw = open(src, "rb").read()
    if hashlib.md5(raw).hexdigest() != FROM_PIN:
        out("%s is %s, not the FROM pin %s -- STOP" % (src, hashlib.md5(raw).hexdigest()[:8], FROM_PIN[:8]))
        return 1
    t = apply(raw.decode("utf-8"), out)
    with open(dst, "wb") as h:
        h.write(t.encode("utf-8"))
    return 0
